+		if errors.Is(err, io.EOF) {
+			return nil
+		}
+		if err != nil {
+			return err
+		}
+		if msg.ID == nil {
+			continue
+		}
+		response := handleMCPMessage(ctx, opts, msg)
+		if err := writeMCPMessage(out, response); err != nil {
+			return err
+		}
+	}
+}
